INSERT INTO public.portfolio_site (id,data) VALUES ('main','{"specialty":"Data Analyst · Applied AI","tagline":"Power BI · SQL · Python","intro":"I turn financial and operational data into clear dashboards, useful insights and practical AI prototypes.","availability":"Open to Data Analyst & Junior BI opportunities","about":"I’m Mostafa, a data analyst based in Giza, Egypt. My focus is financial and operational analytics: preparing data, defining useful KPIs and building reports that make patterns easier to understand. I also build applied AI prototypes in Python.","background":"I completed the Applied AI & Data Analysis diploma at Digilians and am awaiting the certificate. My background combines ERP technical support, a Bachelor of Laws from Cairo University, and Microsoft Power BI and Google Data Analytics credentials.","email":"mostafa.eltaweel000@gmail.com","phone":"+201112611898","location":"Giza, Egypt · Open to remote and on-site roles","linkedin":"https://www.linkedin.com/in/mostafa-eltaweel/","github":"https://github.com/mostafaeltaweel","resume":"assets/Resume.pdf","portrait":"assets/images/portrait.png","diploma":"Applied AI & Data Analysis Diploma","diplomaStatus":"Completed · Certificate pending","diplomaDescription":"Completed professional training in applied AI and data analysis, with practical work across Power BI, SQL, Python, statistics and machine learning. Awaiting the issued certificate.","trainingSummary":"Applied AI & Data Analysis diploma completed at Digilians. Certificate pending; Microsoft Power BI and Google Data Analytics credentials are listed below."}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public.portfolio_projects (id,data) VALUES ('business-performance','{"title":"Business Performance Report","category":"Power BI · DAX · Power Query","description":"A downloadable Power BI report for exploring performance through interactive filters, KPI summaries, transformed source data, and time-based DAX calculations.","image":"assets/images/macbook.jpg","imageAlt":"Business Performance Power BI Report","order":50,"visible":true,"wide":false,"isNew":false,"links":[{"label":"Download Project","url":"power-bi-projects-main.zip","download":true}],"id":"business-performance","group":"Analytics & BI","problem":"How can business performance be reviewed through a reusable reporting view?","approach":"Created a Power BI report with Power Query transformations, DAX measures, filters and KPI summaries.","outcome":"A downloadable report for inspecting the analysis and interacting with the available filters.","limitations":"Portfolio work. No client results or independently measured business savings are claimed."}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public.portfolio_projects (id,data) VALUES ('electricity-theft','{"title":"Electricity Theft Detection","category":"Machine Learning & Explainable AI","description":"A Streamlit prototype for exploring smart-meter risk with a dual-branch CNN-LSTM model and engineered consumption features.","image":"assets/images/electricity-theft.jpg","imageAlt":"Electricity Theft Detection Dashboard","order":30,"visible":true,"wide":true,"isNew":false,"links":[{"label":"Live Demo","url":"https://theft-electric-detection-c.streamlit.app/","download":false}],"id":"electricity-theft","group":"Applied AI","problem":"How can electricity-consumption patterns help prioritize unusual meters for review?","approach":"Combined temporal modeling with engineered statistical features and packaged the model in a Streamlit risk-scoring interface.","outcome":"An interactive demonstration of the workflow from consumption data to a model-assisted risk score.","limitations":"Portfolio prototype using benchmark and simulated theft scenarios. A risk score is not proof of theft. Model performance must be reviewed against the evaluation protocol before operational use."}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public.portfolio_projects (id,data) VALUES ('emolens','{"title":"EmoLens — Facial Emotion Recognition","category":"Deep Learning & Computer Vision","description":"A computer-vision prototype with image, camera and video inputs, built around EfficientNet-B3 and attention-based classification.","image":"assets/images/emolens.jpg","imageAlt":"EmoLens Facial Emotion Recognition","order":40,"visible":true,"wide":true,"isNew":false,"links":[{"label":"Live Demo","url":"https://facial-emotion-recognition-m.streamlit.app/","download":false}],"id":"emolens","group":"Applied AI","problem":"How can a trained image classifier be made accessible through an interactive application?","approach":"Used EfficientNet-B3 with CBAM attention, dataset deduplication and confidence calibration, then added camera, upload and video interfaces.","outcome":"An end-to-end demonstration of model integration, prediction presentation and multiple input formats.","limitations":"Predicted facial-expression labels do not establish a person’s internal emotional state. This is a learning prototype, not a clinical or employment assessment tool."}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public.portfolio_projects (id,data) VALUES ('feed-calculator','{"title":"Feed Formulation Calculator","category":"React · PWA · Offline-first","description":"Arabic RTL application replacing spreadsheet-based feed formulation with instant nutritional calculations, cost analysis, saved recipes, protected admin controls, Excel/PDF export, and full offline support.","image":"assets/images/feed-calculator.png","imageAlt":"Feed Formulation Calculator PWA","order":60,"visible":true,"wide":true,"isNew":false,"links":[{"label":"Live Demo","url":"https://mostafaeltaweel.github.io/feed-calculator-pwa/","download":false},{"label":"GitHub","url":"https://github.com/mostafaeltaweel/feed-calculator-pwa","download":false}],"id":"feed-calculator","group":"Tools & Automation","problem":"How can a spreadsheet-based formulation task become easier to use and repeat?","approach":"Built an Arabic RTL React PWA with nutritional calculations, cost analysis, saved recipes and spreadsheet/PDF export.","outcome":"A live application and source repository demonstrate how a calculation workflow can become an accessible tool.","limitations":"Calculations depend on the supplied ingredient data. Formulations require review by a qualified domain professional before practical use."}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public.portfolio_projects (id,data) VALUES ('financial-fraud','{"id":"financial-fraud","title":"Financial Fraud Analytics","category":"Power BI · Financial Analytics","group":"Analytics & BI","description":"Explore transaction patterns and fraud labels in synthetic financial data. A Power BI report with transaction-type filters, KPI summaries and time-based views.","image":"assets/images/financial-fraud.png","imageAlt":"Financial fraud dashboard showing transaction totals, labeled fraud cases and fraud rates by transaction type","order":10,"visible":true,"wide":true,"isNew":true,"problem":"Where are fraud-labeled transactions concentrated, and how do transaction types compare in a synthetic financial dataset?","approach":"Built a Power BI report with measures for transaction count, transaction amount, fraud count, fraud rate and fraud-labeled amount. Added transaction-type filters, comparisons and simulation-time views.","outcome":"The supplied report snapshot shows about 1.049 million transactions and 1,142 fraud-labeled transactions (0.11%). The visible fraud cases are in CASH_OUT (578) and TRANSFER (564). The report file is available for inspection in Power BI Desktop.","limitations":"Synthetic data for portfolio analysis. Counts describe the supplied screenshot and its filter state, not a live financial system. Fraud-labeled amount is not money recovered or fraud prevented. Time-axis sorting and rate denominators should be checked before operational interpretation.","links":[{"label":"Download Power BI · 62 MB","url":"assets/downloads/Synthetic_Financial_datasets.pbix","download":true},{"label":"View dashboard image","url":"assets/images/financial-fraud.png","download":false}]}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public.portfolio_projects (id,data) VALUES ('life-manager','{"title":"Life Manager — Smart Excel System","category":"Excel · Dashboard · Data Automation","description":"Connected Arabic workbook unifying goals, habits, budget, savings, balance, gratitude, and settings in a single visual management system with validated inputs and automated summaries.","image":"assets/images/life-manager-dashboard.png","imageAlt":"Life Manager Arabic Excel dashboard","order":70,"visible":true,"wide":true,"isNew":false,"links":[{"label":"Download Workbook","url":"%D9%85%D8%AF%D9%8A%D8%B1%20%D8%A7%D9%84%D8%AD%D9%8A%D8%A7%D9%87/outputs/life-manager/Life_Manager.xlsx","download":true}],"id":"life-manager","group":"Tools & Automation","problem":"How can personal goals, habits and budgets be tracked in one connected workbook?","approach":"Organized an Arabic Excel system around validated inputs and linked summaries for goals, savings and everyday tracking.","outcome":"A downloadable workbook with a dashboard and coordinated tracking sheets.","limitations":"A personal-productivity demonstration. Financial entries and outcomes depend on the user’s own inputs."}'::jsonb) ON CONFLICT DO NOTHING;
INSERT INTO public.portfolio_projects (id,data) VALUES ('powerbi-survey','{"title":"Data Professional Survey Dashboard","category":"Power BI & Business Analytics","description":"A Power BI dashboard exploring compensation, tools and career satisfaction across a survey of 630 data professionals.","image":"assets/images/powerbi-survey.jpg","imageAlt":"Data Professional Survey Dashboard","order":20,"visible":true,"wide":true,"isNew":false,"links":[{"label":"Watch Demo","url":"assets/images/powerbi-survey-demo.mp4","download":false}],"id":"powerbi-survey","group":"Analytics & BI","problem":"What patterns in roles, compensation and career satisfaction appear in a data-professional survey?","approach":"Presented geographic distribution, salary by role, tool preferences and satisfaction measures in an interactive dashboard.","outcome":"A visual summary that lets viewers compare the survey responses. A recorded walkthrough is available.","limitations":"A self-reported survey reflects its respondents and sampling limits. It is not a representative salary benchmark for every market."}'::jsonb) ON CONFLICT DO NOTHING;
